#include <iostream>
#include <map>
int main() {
    std::map<char, int> m;
    m['b'] = 2; m['a'] = 1; m['c'] = 3;
    for (auto& p : m) std::cout << p.first;
}

#include <iostream>
#include <string>
#include <unordered_map>
int main() {
    std::unordered_map<char, int> f;
    std::string s = "abab";
    for (char c : s) f[c]++;
    std::cout << f['a'] << f['b'];
}

#include <iostream>
#include <unordered_map>
int main() {
    int a[] = {2, 7, 11, 15}, target = 9;
    std::unordered_map<int, int> pos;
    for (int i = 0; i < 4; i++) {
        auto it = pos.find(target - a[i]);
        if (it != pos.end()) { std::cout << it->second << i; return 0; }
        pos[a[i]] = i;
    }
    std::cout << "none";
}

#include <iostream>
#include <unordered_set>
int main() {
    int a[] = {1, 2, 3, 2, 4};
    std::unordered_set<int> seen;
    int dups = 0;
    for (int x : a)
        if (!seen.insert(x).second) dups++;
    std::cout << dups;
}

#include <iostream>
#include <set>
int main() {
    std::multiset<int> ms;
    for (int x : {5, 1, 5, 2}) ms.insert(x);
    ms.erase(ms.find(5));
    std::cout << ms.count(5) << " " << ms.size();
}
